    @inline(__always)
    private func checkMultiplyAddingComplexConjugateConstantABAlternating(
        _ aEven: Lane,
        _ aOdd: Lane,
        _ bEven: Lane,
        _ bOdd: Lane
    ) {
        let mismatches = Mismatches(
            "multiplyAddingComplexConjugate with a alternating \(hex(aEven)), \(hex(aOdd)), b alternating \(hex(bEven)), \(hex(bOdd))"
        )
        let cInputs = Inputs.vectors(H.self, seed: 0x0E4E_945B_CF1A_E9FC)
        mismatches.check(
            H.repeatingBlock(aEven, aOdd, aEven, aOdd, aEven, aOdd, aEven, aOdd),
            H(
                raw: HighwayReference.repeatingBlockU16(
                    aEven,
                    aOdd,
                    aEven,
                    aOdd,
                    aEven,
                    aOdd,
                    aEven,
                    aOdd
                )
            ),
            "repeatingBlock"
        )
        mismatches.check(
            H.repeatingBlock(bEven, bOdd, bEven, bOdd, bEven, bOdd, bEven, bOdd),
            H(
                raw: HighwayReference.repeatingBlockU16(
                    bEven,
                    bOdd,
                    bEven,
                    bOdd,
                    bEven,
                    bOdd,
                    bEven,
                    bOdd
                )
            ),
            "repeatingBlock"
        )
        for c in cInputs {
            mismatches.check(
                H.multiplyAddingComplexConjugate(
                    H.repeatingBlock(aEven, aOdd, aEven, aOdd, aEven, aOdd, aEven, aOdd),
                    H.repeatingBlock(bEven, bOdd, bEven, bOdd, bEven, bOdd, bEven, bOdd),
                    c
                ),
                H(
                    raw: HighwayReference.multiplyAddingComplexConjugateU16(
                        H.repeatingBlock(aEven, aOdd, aEven, aOdd, aEven, aOdd, aEven, aOdd).raw,
                        H.repeatingBlock(bEven, bOdd, bEven, bOdd, bEven, bOdd, bEven, bOdd).raw,
                        c.raw
                    )
                ),
                "c: \(describe(c))"
            )
        }
        mismatches.record()
    }

